    """
def fizzbuzz(n: Any) -> object {
    final = [];
    for i in range(1, (n + 1)) {
        if (((i % 3) == 0) and ((i % 5) == 0)) {
            final.append("FizzBuzz");
        } elif ((i % 3) == 0) {
            final.append("Fizz");
        } elif ((i % 5) == 0) {
            final.append("Buzz");
        } else {
            final.append(i);
        }
    }
    return final;
}

