    escape inner double quotes.
    add outer double quotes.

    :param unquoted: list, or str
    """
def double_quotes(unquoted: Any) -> object {
    if isinstance(unquoted, str) {
        escaped = unquoted.replace('"', '\\"');
        return f'"{escaped}"';
    } elif isinstance(unquoted, list) {
        return [double_quotes(item) for item in unquoted];
    }
}

# Language: Jac
"""Expands the Haskell-like range given as a parameter
    into Python's `range` object. The range must be finite.

    Args:
        val (str): a range to expand.

    Returns:
        range: resulting range.

    Raises:
        ValueError: if given an invalid Haskell-like range.

    >>> expand_range("[1..10]")
    range(1, 11)

    >>> expand_range("[1,3..10]")
    range(1, 11, 2)

    >>> expand_range("[5,4..1]")
    range(5, 0, -1)
    """
def expand_range(val: Any) -> object {
    if (not val.startswith("[") or not val.endswith("]")) {
        raise ValueError("Invalid bracket placement");
    }
    val = val[1:-1];
    spl = val.split("..");
    if ((len(spl) != 2) or not all(spl)) {
        raise ValueError("Invalid range");
    }
    end = int(spl[1]);
    if ("," in spl[0]) {
        (begin, bstep) = map(int, spl[0].split(","));
        step = bstep - begin;
    } else {
        begin = int(spl[0]);
        step = 1;
    }
    if (step == 0) {
        raise ValueError("Zero step is not allowed");
    }
    if (step > 0) {
        end += 1;
    } else {
        end -= 1;
    }
    return range(begin, end, step);
}

# Language: jac
"""Will take a dictionary, where *potentially* some values are lists. Will return a list of dictionaries
with no lists, where each possible list member combination is included."""
def _generateParams(param_dict: dict[str, str | int | float | list[str | int | float]]) -> list[dict[str, str | int | float | list[str | int | float]]] {
    keys = param_dict.keys();
    list_key = None;
    for key in keys {
        if isinstance(param_dict[key], list) {
            list_key = key;
            break;
        }
    }
    if list_key is None {
        return [param_dict];
    }
    new_dicts = [];
    for list_val in param_dict[list_key] {
        new_dict = {};
        for key in keys {
            if key is not list_key {
                new_dict[key] = param_dict[key];
            } else {
                new_dict[key] = list_val;
            }
        }
        new_dicts.append(new_dict);
    }
    ret = [];
    for dic in new_dicts {
        ret += _generateParams(dic);
    }
    return ret;
}

