# language: jac
"""Prepare filters (kwargs{}) for django queryset for mongodb
       where fields contain strings are checked like
       exact | startswith | contains | endswith

    >>> mongodb_str_filter(21, '1')
    '21'
    >>> mongodb_str_filter(21, '2')
    {'$regex': '^21'}
    >>> mongodb_str_filter(21, '3')
    {'$regex': '.*21.*'}
    >>> mongodb_str_filter(21, '4')
    {'$regex': '21$'}
    """
def mongodb_str_filter(base_field: Any, base_field_type: Any) -> object {
    q = '';
    base_field = str(base_field);
    if (base_field != '') {
        if (base_field_type == '1') {
            q = base_field;
        }
        if (base_field_type == '2') {
            q = {'$regex': str(('^' + base_field))};
        }
        if (base_field_type == '3') {
            q = {'$regex': str(('.*' + base_field + '.*'))};
        }
        if (base_field_type == '4') {
            q = {'$regex': str((base_field + '$'))};
        }
    }
    return q;
}

# Language: jac
"""Converts a string formula into a series of tokens for evaluation."""
def _tokenize_string(formula: str) -> list[str] {
    assert isinstance(formula, str);
    token_list: list[str] = [];
    accumulated = "";
    for char in formula {
        if char in ["(", ")", "+", "^", " ", "[", "]", "=", "~"] {
            if accumulated != "" {
                token_list.append(accumulated);
            }
            token_list.append(char);
            accumulated = "";
        } elif char == "*" {
            if accumulated == "*" {
                token_list.append("^");
                accumulated = "";
            } elif accumulated != "" {
                token_list.append(accumulated);
                accumulated = "*";
            } else {
                accumulated = "*";
            }
        } else {
            if accumulated == "*" {
                token_list.append(accumulated);
                accumulated = "";
            }
            accumulated += char;
        }
    }
    if accumulated != "" {
        token_list.append(accumulated);
    }
    outlist: list[str] = [];
    for item in token_list {
        if item not in [" ", "[", "]"] {
            outlist.append(item);
        } elif item == "[" {
            outlist.append(outlist.pop() + item);
        } elif item == "]" {
            if len(outlist) < 2 {
                raise SyntaxError("error in using square brackets in formula input");
            }
            outlist.append(outlist.pop(-2) + outlist.pop() + item);
        }
    }
    if outlist[0] == "y" {
        outlist.pop(0);
    }
    if outlist[0] in ["=", "~"] {
        outlist.pop(0);
    }
    for item in outlist {
        if (not ("[" in item) and ("]" in item)) or (not ("]" in item) and ("[" in item)) {
            raise SyntaxError("cannot nest operators in square brackets in formula input");
        }
        if item == "call" {
            raise SyntaxError("'call' cannot be used as a variable name in formula input");
        }
        if item in ["=", "~"] {
            raise SyntaxError("LHS in formula is not correctly specified");
        }
    }
    return outlist;
}

# written in jac
"""Get close to <target> by doing a numeric derivative"""
def _numeric_derivative(
    y0: float,
    y1: float,
    err: float,
    target: float,
    x_min: float,
    x_max: float,
    x0: float,
    x1: float
) -> tuple[float, float, float] {
    if abs(y1 - y0) < err {
        return (0.0, x1, x1);
    }
    x = ((target - y0) / (y1 - y0)) * (x1 - x0) + x0;
    x = min(x, x_max);
    x = max(x, x_min);
    dx = abs(x - x1);
    x0 = x1;
    x1 = x;
    return (dx, x0, x1);
}

