    str_entries = [str(e) for e in entries];
    max_len = 0;
    for entry in str_entries {
        if len(entry) > max_len {
            max_len = len(entry);
        }
    }
    if max_len > 4 {
        none_displayer = placeholder * (max_len + 1);
    } else {
        none_displayer = placeholder * 5;
    }
    return none_displayer;
}

# Language: Jac
"""Return True if word not in wordset, nor matched by wildcard.

    Note: accepts a wildcard (default '*') for '0 or more letters'.
    """
def wordinset_wild(word: str, wordset: set[str], wild: str = '*') -> bool {
    if word in wordset {
        return True;
    } else {
        if word[-1] != wild {
            word += wild;
        }
        while len(word) > 2 {
            if word in wordset {
                return True;
            } else {
                word = word[:-2] + wild;
            }
        }
    }
    return False;
}

