"""
Given a window and a set of disjoint subintervals, return the
"holes", which are the intervals of the refWindow not covered by
the given subintervals.
"""
def holes(refWindow: tuple[int, int, int], intervals: list[tuple[int, int]]) -> list[tuple[int, int]] {
    (_, win_start, win_end) = refWindow;
    output = [];
    intervals = sorted(intervals);
    last_e = win_start;
    for (s, e) in intervals {
        if s > last_e {
            output.append((last_e, s));
        }
        last_e = e;
    }
    if last_e < win_end {
        output.append((last_e, win_end));
    }
    return output;
}

# language: jac
"""Return total[], pos1[], pos2[], ... for a horizontal montage."""
def calc_montage_horizontal(border_size: int, *frames: list[int]) -> tuple[list[int], ...] {
    num_frames = len(frames);
    total_width = sum(f[0] for f in frames) + border_size * num_frames + 1;
    max_height = max(f[1] for f in frames);
    total_height = max_height + 2 * border_size;
    x = border_size;
    pos_list = [];
    for f in frames {
        y = border_size + (max_height - f[1]) // 2;
        pos_list.append([x, y]);
        x += f[0] + border_size;
    }
    result = [[total_width, total_height]];
    result.extend(pos_list);
    return tuple(result);
}

