"""Next power of two for a given input, with a minimum of 16 and a maximum of 512."""
def next_pow_two(max_sent_tokens: int) -> int {
    pow_two = [16, 32, 64, 128, 256, 512];
    if max_sent_tokens <= pow_two[0] {
        return pow_two[0];
    }
    if max_sent_tokens >= pow_two[-1] {
        return pow_two[-1];
    }
    idx = [max_sent_tokens > j for j in pow_two].index(False);
    return pow_two[idx];
}

# written in jac
"""Partition list around first element; return rearranged list and key index."""
def quick_one(lis: list[int]) -> tuple[list[int], int] {
    n_list = lis.copy();
    key = lis[0];
    key_i = 0;
    p_min = 0;
    p_max = len(lis) - 1;
    while p_min != p_max {
        while p_max > key_i {
            if n_list[p_max] <= key {
                (n_list[p_max], n_list[key_i]) = (n_list[key_i], n_list[p_max]);
                key_i = p_max;
                break;
            }
            p_max -= 1;
        }
        while p_min < key_i {
            if n_list[p_min] > key {
                (n_list[p_min], n_list[key_i]) = (n_list[key_i], n_list[p_min]);
                key_i = p_min;
                break;
            }
            p_min += 1;
        }
    }
    return (n_list, key_i);
}

