# Language: Jac
"""Binary search for item in arr between left and right indices."""
def binary_search(arr: list[int], left: int, right: int, item: int) -> int {
    if right >= left {
        mid = left + (right - left) // 2;
        if arr[mid] == item {
            return mid;
        }
        if arr[mid] > item {
            return binary_search(arr, left, mid - 1, item);
        }
        return binary_search(arr, mid + 1, right, item);
    }
    return -1;
}

# Language: jac
"""Selection partition."""
def partition(array: list[int], pivot: int) -> int {
    i = -1;
    j = 0;
    while j < len(array) - 1 {
        if array[j] == pivot {
            (array[-1], array[j]) = (array[j], array[-1]);
            continue;
        } elif array[j] < pivot {
            i += 1;
            (array[i], array[j]) = (array[j], array[i]);
        }
        j += 1;
    }
    (array[-1], array[i + 1]) = (array[i + 1], array[-1]);
    return i + 1;
}

