# Language: jac
glob BYTE_MASK = 0xFF;

"""Convert a byte-string to a signed integer."""
def bin2sint(data: bytes) -> int {
    number = 0;
    arr = list(data);
    byteslen = len(data);
    negative = arr[byteslen - 1] >= 128;
    for (idx, byte_val) in enumerate(arr) {
        if negative {
            byte_val = byte_val ^ BYTE_MASK;
        }
        number += byte_val * (256 ** idx);
    }
    if negative {
        number = (number + 1) * -1;
    }
    return number;
}

# Language: Jac
"""Checks to see if a task is complete."""
def is_task_complete(
    task: dict[str, str | int],
    task_runs: list[dict[str, str | int]],
    redundancy: int,
    task_id_field: str = 'id',
    task_run_id_field: str = 'task_id',
    error: bool | None = None
) -> bool | None {
    if redundancy <= 0 {
        return error;
    }
    count = 0;
    task_id = task[task_id_field];
    for tr in task_runs {
        tr_id = tr[task_run_id_field];
        if task_id == tr_id {
            count += 1;
            if count >= redundancy {
                return True;
            }
        }
    }
    return False;
}

