        }
        return p;
    }
    k1 = _getclip(x1, y1);
    k2 = _getclip(x2, y2);
    while (k1 | k2) != 0 {
        if (k1 & k2) != 0 {
            return (None, None, None, None);
        }
        opt = k1 or k2;
        if opt & UPPER {
            x = x1 + ((x2 - x1) * (1.0 * (bottom - y1))) / (y2 - y1);
            y = bottom;
        } elif opt & LOWER {
            x = x1 + ((x2 - x1) * (1.0 * (top - y1))) / (y2 - y1);
            y = top;
        } elif opt & RIGHT {
            y = y1 + ((y2 - y1) * (1.0 * (right - x1))) / (x2 - x1);
            x = right;
        } elif opt & LEFT {
            y = y1 + ((y2 - y1) * (1.0 * (left - x1))) / (x2 - x1);
            x = left;
        } else {
            raise RuntimeError("invalid clipping state");
        }
        if opt == k1 {
            (x1, y1) = (x, y);
            k1 = _getclip(x1, y1);
        } else {
            (x2, y2) = (x, y);
            k2 = _getclip(x2, y2);
        }
    }
    return (x1, y1, x2, y2);
}

