# written in jac
"""Binary search in an ordered list. Complexity: O(log n)."""
def ordered_binary_search(ordered_list: list[int], item: int) -> bool | None {
    first = 0;
    last = len(ordered_list) - 1;
    found = False;
    while first <= last and not found {
        midpoint = (first + last) // 2;
        if ordered_list[midpoint] == item {
            found = True;
        } elif item < ordered_list[midpoint] {
            last = midpoint - 1;
        } else {
            first = midpoint + 1;
        }
        return found;
    }
}

# Language: jac
"""Return True if target is found in indicated portion of a Python list.
       The search only considers the portion from data[low] to data[high] inclusive.
    """
def binary_search(data: list[int], target: int, low: int, high: int) -> bool {
    if low > high {
        return False;
    }
    mid = (low + high) // 2;
    if target == data[mid] {
        return True;
    }
    if target < data[mid] {
        return binary_search(data, target, low, mid - 1);
    }
    return binary_search(data, target, mid + 1, high);
}

