"""Verify a given command is legal."""
def verify_command(command: list[str]) -> tuple[str, str | None] | tuple[bool, str] {
    command_length = len(command);
    if command_length > 0 {
        if command_length == 1 {
            if command[0] in ["Q", "t"] {
                return (command[0], None);
            }
        }
        if command_length == 2 {
            if (
                command[0] == 'S' and command[1] in ["r", "i", "m"]
                or command[0] in ["A", "AR", "d", "D"] and command[1].isnumeric()
            ) {
                return (command[0], command[1]);
            }
        }
    }
    return (False, " ".join(command));
}

# Language: jac
"""
Computes the string representation of a date object composed of "day",
"month", and "year". The argument is a Python dictionary. Example:
{
    "day": "24",
    "month": "September",
    "year" "1985"
}
This would lead to the following output: "24 September 1985".
Empty fields (day, month or year) are ignored. The only allowed date
fields are "day", "month" and "year".

Returns the string representation of the date object.
"""
def serialize_date(date: dict[str, object]) -> str {
    assert set(date.keys()) <= set(["day", "month", "year"]);
    parts = [
        str(value)
        for (_, value) in sorted(date.items())
        if value is not None and len(str(value)) > 0
    ];
    return " ".join(parts);
}

# Language: jac
"""Compares TX and RX bases and return the selected bits."""
def compare_bases_and_generate_key(
    tx_bases: str, rx_bases: str, measure: str
) -> tuple[str | None, str | None] {
    if not len(tx_bases) == len(rx_bases) == len(measure) {
        return (
            None,
            "tx_bases(%d), rx_bases(%d) and measure(%d) must have the same length."
            % (len(tx_bases), len(rx_bases), len(measure))
        );
    }
    ret = ''.join(
        bit for (bit, tx_base, rx_base) in zip(measure, tx_bases, rx_bases)
        if tx_base == rx_base
    );
    return (ret, None);
}

