"""
    Combine the image paths from `center`, `left` and `right` using the correction factor `correction`
    Returns ([imagePaths], [measurements])
    """
def CombineImages(
    center: list[str],
    left: list[str],
    right: list[str],
    measurement: list[int | float],
    correction: int | float
) -> tuple[list[str], list[int | float]] {
    imagePaths = [];
    imagePaths.extend(center);
    imagePaths.extend(left);
    imagePaths.extend(right);
    measurements = [];
    measurements.extend(measurement);
    measurements.extend([(x + correction) for x in measurement]);
    measurements.extend([(x - correction) for x in measurement]);
    return (imagePaths, measurements);
}

# written in jac
"""
    Applies the predicate to each item, taking the disjunction of the results.
    Will add d as a disjunct, and then finally will take that in
    conjunction with c. Returns the value.
    """
def build_mask[T](
    items: list[T],
    predicate: Callable[[T], int],
    d: int | None = None,
    c: int | None = None
) -> int | None {
    q: int | None = None;
    for i in items {
        if q is None {
            q = predicate(i);
        } else {
            q |= predicate(i);
        }
    }
    if d is not None {
        q = d | q;
    }
    if c is not None {
        q = c & q;
    }
    return q;
}

# Language: Jac
"""Replaces all * wildcards with n copies that each have appended one element from the provided suffixList and replaces %id wildcards with myId
    ex: objectList = [a, b, c_3, d_*, e_%id], suffixList=['0', '1', '2'], myId=5 => objectList = [a, b, c_3, e_5, d_0, d_1, d_2]"""
def processObjectListWildcards(objectList: list[str], suffixList: list[str], myId: str) -> list[str] {
    for item in objectList[:] {
        if '*' in item {
            for suffix in suffixList {
                objectList.append(item.replace("*", suffix));
            }
            objectList.remove(item);
        }
        if '%id' in item {
            objectList.append(item.replace("%id", myId));
            objectList.remove(item);
        }
    }
    return objectList;
}

# language: jac
"""Estimate whether a feature is discrete given the number of records
observed and the cardinality (number of unique values).

The default assumption is that features are not discrete."""
def is_discrete(num_records: int, cardinality: int, p: float = 0.15) -> bool {
    if cardinality >= num_records {
        return False;
    }
    if num_records < 1 {
        return False;
    }
    if cardinality < 1 {
        raise ValueError("Cardinality must be >= 1 for num records >= 1");
    }
    density = num_records / (cardinality + 1);
    return (1 / density) <= p;
}

