"""Removes corporation suffix from developer names, if present.

    Args:
        dev (str): Name of app developer.

    Returns:
        str: Name of app developer with suffixes stripped.
    """
def strip_dev_suffix(dev: Any) -> object {
    corp_suffixes = (
        "incorporated",
        "corporation",
        "limited",
        "oy/ltd",
        "pty ltd",
        "pty. ltd",
        "pvt ltd",
        "pvt. ltd",
        "s.a r.l",
        "sa rl",
        "sarl",
        "srl",
        "corp",
        "gmbh",
        "l.l.c",
        "inc",
        "llc",
        "ltd",
        "pvt",
        "oy",
        "sa",
        "ab"
    );
    if (dev not in (None, "")) {
        for suffix in corp_suffixes {
            if dev.lower().rstrip(" .").endswith(suffix) {
                dev = dev.rstrip(" .")[:(len(dev) - len(suffix) - 1)].rstrip(",. ");
                break;
            }
        }
    }
    return dev;
}

# Jac lang
"""Tokenize a SMILES molecule or reaction."""
def smi_spliter(smi: str) -> list[str] {
    import re;
    pattern = "(\[[^\]]+]|Br?|Cl?|N|O|S|P|F|I|b|c|n|o|s|p|\(|\)|\.|=|#|-|\+|\\\\|\/|:|~|@|\?|>|\*|\$|\%[0-9]{2}|[0-9])";
    regex = re.compile(pattern);
    tokens = [token for token in regex.findall(smi)];
    assert smi == ''.join(tokens);
    return tokens;
}

# language: jac
"""Returns n counters after the increment and max operations coded in array."""
def solution(n: int, array: list[int]) -> list[int] {
    counters = [0] * n;
    max_count = 0;
    last_max_value = 0;
    for val in array {
        if val == n + 1 {
            last_max_value = max_count;
        } else {
            if counters[val - 1] < last_max_value {
                counters[val - 1] = last_max_value + 1;
            } else {
                counters[val - 1] += 1;
            }
            if counters[val - 1] > max_count {
                max_count = counters[val - 1];
            }
        }
    }
    return [max(i, last_max_value) for i in counters];
}

