"""Determine the type of a value, returning a full-path module.name string."""
def DetermineType[T](value: T) -> str | None {
    object_type = type(value);
    if not hasattr(object_type, '__name__') {
        return None;
    }
    type_string = getattr(object_type, '__module__', '');
    if type_string {
        type_string += '.';
    }
    type_string += object_type.__name__;
    return type_string;
}

# Jac lang
"""Calculate union of probabilities p_1 U p_2 U ... U p_n."""
def union(probs: list[float]) -> float {
    while len(probs) > 1 {
        if len(probs) % 2 {
            (p, probs) = (probs[0], probs[1:]);
            probs[0] = probs[0] + p - probs[0] * p;
        }
        probs = [
            probs[i - 1] + probs[i] - probs[i - 1] * probs[i]
            for i in range(1, len(probs), 2)
        ];
    }
    return probs[0];
}

