def timezone_choice(tzname: str, country: str | None = None) -> tuple[str, str] {
    try {
        (base, rest) = tzname.split('/', 1);
    } except ValueError {
        (base, rest) = (None, tzname);
    }
    rest = rest.replace('_', ' ');
    try {
