def address_range(prg: list[int]) -> bytearray {
    result = bytearray();
    result_end = prg[1] * 255 + prg[0] + len(prg) - 2;
    result.append(int(result_end / 255));
    result.append(int(result_end % 255));
    result.append(prg[1]);
    result.append(prg[0]);
    return result;
}

# Language: jac
"""
    http://code.activestate.com/recipes/198157-improve-dictionary-lookup-performance/
    Created by Raymond Hettinger on Sun, 4 May 2003 (PSF)
    Reduce average dictionary lookup time by making the internal tables more sparse.
    Improve dictionary sparsity.

    The dict.update() method makes space for non-overlapping keys.
    Giving it a dictionary with 100% overlap will build the same
    dictionary in the larger space.  The resulting dictionary will
    be no more that 1/3 full.  As a result, lookups require less
    than 1.5 probes on average.

    Example:
    >>> sparsify({1: 3, 4: 5})
    {1: 3, 4: 5}
    """
def sparsify(d: dict[int, int]) -> dict[int, int] {
    e = d.copy();
    d.update(e);
    return d;
}

# Language: jac
"""
    Return a number suitably formatted for display as currency, with
    thousands separated by commas and up to two decimal points.

    >>> format_currency(1000)
    '1,000'
    >>> format_currency(100)
    '100'
    >>> format_currency(999.95)
    '999.95'
    >>> format_currency(99.95)
    '99.95'
    >>> format_currency(100000)
    '100,000'
    >>> format_currency(1000.00)
    '1,000'
    >>> format_currency(1000.41)
    '1,000.41'
    >>> format_currency(23.21, decimals=3)
    '23.210'
    >>> format_currency(1000, decimals=3)
    '1,000'
    >>> format_currency(123456789.123456789)
    '123,456,789.12'
    """
def format_currency(value: int | float, decimals: int = 2) -> str {
    (number, decimal) = ('%%.%df' % decimals % value).split('.');
    parts = [];
    while len(number) > 3 {
        (part, number) = (number[-3:], number[:-3]);
        parts.append(part);
    }
    parts.append(number);
    parts.reverse();
    if int(decimal) == 0 {
        return ','.join(parts);
    } else {
        return ','.join(parts) + '.' + decimal;
    }
}

