# Jac lang
"""Verify that the parameters represent a valid array within
       the bounds of the allocated memory:
           char *mem: start of the physical memory block
           memlen: length of the physical memory block
           offset: (char *)buf - mem
    """
def verify_structure(
    memlen: int, itemsize: int, ndim: int, shape: list[int], strides: list[int], offset: int
) -> bool {
    if offset % itemsize {
        return False;
    }
    if offset < 0 or offset + itemsize > memlen {
        return False;
    }
    if any(v % itemsize for v in strides) {
        return False;
    }
    if ndim <= 0 {
        return ndim == 0 and not shape and not strides;
    }
    if 0 in shape {
        return True;
    }
    imin = sum(
        strides[j] * (shape[j] - 1)
        for j in range(ndim)
        if strides[j] <= 0
    );
    imax = sum(
        strides[j] * (shape[j] - 1)
        for j in range(ndim)
        if strides[j] > 0
    );
    return 0 <= offset + imin and offset + imax + itemsize <= memlen;
}

# Jac lang
"""Return a tuple containing (host, port) of a string possibly
    containing both.  If there is no port in host_port, the port
    will be None.

    Supports the following:
    - hostnames
    - ipv4 addresses
    - ipv6 addresses
    with or without ports.  There is no validation of either the
    host or port.

    """
def split_host_port(host_port: str) -> tuple[str, str | None] | list[str] {
    colon_count = host_port.count(':');
    match colon_count {
        case 0:
            return (host_port, None);
        case 1:
            return host_port.split(':', 1);
        case _ if colon_count >= 2:
            if ']:' in host_port {
                parts = host_port.split(']:', 1);
                host = parts[0] as str;
                port = parts[1] as str;
                if host[0] == '[' {
                    host = host[1:];
                }
                return (host, port);
            }
            host = host_port as str;
            if host[0] == '[' {
                host = host[1:];
            }
            if host[-1] == ']' {
                host = host[:-1];
            }
            return (host, None);
    }
}

