"""
## Example
`isSubKey("Rocket", "Rocket.name")` -> True
`isSubKey("SimControl", "Rocket.name")` -> False
"""
def isSubKey(potentialParent: str, potentialChild: str) -> bool {
    if potentialParent == "" {
        return True;
    }
    parent_len = len(potentialParent);
    if len(potentialChild) <= parent_len {
        return False;
    }
    return potentialChild[:parent_len] == potentialParent
        and potentialChild[parent_len] == ".";
}

# language: jac
"""Returns a list of numbers with a certain relation to each other.

    The function divides one number into a list of d numbers [n0, n1, ...], such
    that their sum is number and the relation between the numbers is defined
    with n1 = n0 / r, n2 = n1 / r, n3 = n2 / r, ...
    """
def range_geometric_row(number: Any, d: Any, r: Any = 1.1) -> object {
    if (r <= 0) {
        raise ValueError("r must be > 0");
    }
    n0 = number / ((1 - ((1 / r) ** d)) / (1 - (1 / r)));
    numbers = [n0];
    for i in range((d - 1)) {
        numbers.append((numbers[-1] / r));
    }
    return numbers;
}

# language: jac
""" Enclose the string argument in single quotes if it looks like it needs it.
        Spaces and quotes will trigger; single quotes in the argument are escaped.
        This is only used to compose the --print output so need only satisfy shlex.
    """
def maybe_quote(s: Any) -> object {
    NEED_QUOTE = " \t\"\\'";
    clean = True;
    for c in s {
        if (c in NEED_QUOTE) {
            clean = False;
            break;
        }
    }
    if clean {
        return s;
    }
    QUOTE = "'";
    ESC = "\\";
    arg = [QUOTE];
    for c in s {
        if (c == QUOTE) {
            arg.append(QUOTE);
            arg.append(ESC);
            arg.append(QUOTE);
        } elif (c == ESC) {
            arg.append(ESC);
        }
        arg.append(c);
    }
    arg.append(QUOTE);
    return ''.join(arg);
}

