"""Parsing arguments in op_par_loop to find the correct closing brace"""
def arg_parse(text: Any, j: Any) -> object {
    depth = 0;
    loc2 = j;
    while 1 {
        if (text[loc2] == '(') {
            depth = depth + 1;
        } elif (text[loc2] == ')') {
            depth = depth - 1;
            if (depth == 0) {
                return loc2;
            }
        }
        loc2 = loc2 + 1;
    }
}

# language: jac
"""Read variable length encoded 128 bits unsigned integer."""
def unsigned_leb128_decode(data: Iterator[int]) -> int {
    result = 0;
    shift = 0;
    while True {
        byte: int = next(data);
        result |= (byte & 127) << shift;
        if (byte & 128) == 0 {
            break;
        }
        shift += 7;
    }
    return result;
}

# Language: jac
"""Return AP (Average Precision) with target and results."""
def AP(target: list[object], results: list[list[object]]) -> float {
    n = 1;
    hit = 0;
    ap = 0.0;
    len_target = len(target);
    for res in results {
        (small_set, big_set) = (target, res) if len_target < len(res) else (res, target);
        for item in small_set {
            if item in big_set {
                hit += 1;
                ap += hit / n;
                break;
            }
        }
        n += 1;
    }
    return ap / hit;
}

