        } elif "." in col.lower() {
            c = col.split(".")[-1];
        } else {
            c = col;
        }
        cols.append(c.strip());
    }
    if prefix != None {
        return ", ".join([".".join([prefix, col]) for col in cols]);
    }
    return cols;
}

