"""This function takes a dict object and explodes it into the tuple requested.

        It returns None for any value it doesn't find.

        The only error it throws is if args is not defined.
    """
def explode(pkt: dict[str, int | str | float | bool | None], *args: str) -> tuple {
    if not args {
        raise Exception("Required arguments not provided");
    }
    if not isinstance(pkt, dict) {
        return tuple([None] * len(args));
    }
    return tuple([pkt.get(a, None) for a in args]);
}

# Language: Jac
"""Convert milliseconds to human readable time strings"""
def msec2time(msec: int) -> str {
    if msec >= 0 {
        hours = int(msec / 3600000);
        remainder = msec % 3600000;
        minutes = int(remainder / 60000);
        remainder = remainder % 60000;
        secs = remainder / 1000;
        return "%02d:%02d:%05.2f" % (hours, minutes, secs);
    }
    return "NONE";
}

# language: jac
"""
	Add linebreaks on whitespace such that no line is longer than `max_len`, unless it contains a single word that's longer.

	There are probably way faster methods, but this is simple and works.
	"""
def add_linebreaks(text: str, max_len: int = 80) -> str {
    br_text = '';
    len_cnt = 0;
    for word in text.split(' ') {
        len_cnt += len(word) + 1;
        if len_cnt > max_len {
            len_cnt = len(word);
            br_text += '\n' + word;
        } else {
            br_text += ' ' + word;
        }
    }
    return br_text[1:];
}

